WITH tool_schemas(name, input_schema) AS (
    VALUES
        ('file.read', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"File path relative to workspace root"},"max_bytes":{"type":"integer","minimum":1,"maximum":10485760,"description":"Maximum number of bytes to read"},"encoding":{"type":"string","enum":["utf8","base64"],"description":"Response content encoding"}},"required":["path"]} $$::jsonb),
        ('file.list', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Directory path relative to workspace root"},"pattern":{"type":"string","description":"Glob pattern used to filter entries"},"recursive":{"type":"boolean","description":"Whether to recurse into child directories"}}} $$::jsonb),
        ('file.search', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Directory path to search"},"pattern":{"type":"string","description":"Regular expression pattern"},"file_pattern":{"type":"string","description":"Glob pattern to limit searched files"},"recursive":{"type":"boolean","description":"Whether to recurse into child directories"},"case_insensitive":{"type":"boolean","description":"Whether pattern match is case-insensitive"},"max_results":{"type":"integer","minimum":1,"maximum":500,"description":"Maximum match rows to return"}},"required":["pattern"]} $$::jsonb),
        ('git.status', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Repository path relative to workspace root"}}} $$::jsonb),
        ('git.diff', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Repository path relative to workspace root"},"staged":{"type":"boolean","description":"Whether to diff staged changes"},"ref":{"type":"string","description":"Optional git reference to diff against"},"file_path":{"type":"string","description":"Optional file path filter"}}} $$::jsonb),
        ('git.log', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Repository path relative to workspace root"},"limit":{"type":"integer","minimum":1,"maximum":100,"description":"Maximum commits to return"},"since":{"type":"string","description":"Git --since value"},"author":{"type":"string","description":"Author filter"},"file_path":{"type":"string","description":"Optional file path filter"}}} $$::jsonb),
        ('memory.query', $$ {"type":"object","additionalProperties":false,"properties":{"query":{"type":"string","description":"Memory search query"},"limit":{"type":"integer","minimum":1,"maximum":100,"description":"Maximum memories to return"},"scope":{"type":"string","enum":["org","project","agent"],"description":"Retrieval scope override"}},"required":["query"]} $$::jsonb),
        ('project.list', $$ {"type":"object","additionalProperties":false,"properties":{"limit":{"type":"integer","minimum":1,"maximum":200,"description":"Maximum projects to return"},"cursor":{"type":"string","description":"Opaque pagination cursor"}}} $$::jsonb),
        ('project.get', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"}},"required":["project_id"]} $$::jsonb),
        ('task.list', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Optional project filter"},"status":{"type":"string","description":"Optional work status filter"},"limit":{"type":"integer","minimum":1,"maximum":200,"description":"Maximum tasks to return"},"cursor":{"type":"string","description":"Opaque pagination cursor"}}} $$::jsonb),
        ('task.get', $$ {"type":"object","additionalProperties":false,"properties":{"task_id":{"type":"string","format":"uuid","description":"Task identifier"}},"required":["task_id"]} $$::jsonb),
        ('inbox.list', $$ {"type":"object","additionalProperties":false,"properties":{"status":{"type":"string","enum":["pending","actioned","all"],"description":"Inbox state filter"},"limit":{"type":"integer","minimum":1,"maximum":200,"description":"Maximum inbox items to return"}}} $$::jsonb),
        ('session.list', $$ {"type":"object","additionalProperties":false,"properties":{"scope_type":{"type":"string","description":"Scope type filter"},"scope_id":{"type":"string","format":"uuid","description":"Scope id filter"},"status":{"type":"string","description":"Session status filter"},"limit":{"type":"integer","minimum":1,"maximum":200,"description":"Maximum sessions to return"},"cursor":{"type":"string","description":"Opaque pagination cursor"}}} $$::jsonb),
        ('session.get', $$ {"type":"object","additionalProperties":false,"properties":{"session_id":{"type":"string","format":"uuid","description":"Session identifier"}},"required":["session_id"]} $$::jsonb),
        ('session.history', $$ {"type":"object","additionalProperties":false,"properties":{"session_id":{"type":"string","format":"uuid","description":"Session identifier"},"limit":{"type":"integer","minimum":1,"maximum":500,"description":"Maximum messages to return"},"before_sequence":{"type":"integer","minimum":1,"description":"Return messages strictly before this sequence"}},"required":["session_id"]} $$::jsonb),
        ('agent.list', $$ {"type":"object","additionalProperties":false,"properties":{"class":{"type":"string","description":"Agent class filter"},"status":{"type":"string","description":"Lifecycle status filter"},"limit":{"type":"integer","minimum":1,"maximum":200,"description":"Maximum agents to return"},"cursor":{"type":"string","description":"Opaque pagination cursor"}}} $$::jsonb),
        ('agent.get', $$ {"type":"object","additionalProperties":false,"properties":{"agent_id":{"type":"string","format":"uuid","description":"Agent identifier"}},"required":["agent_id"]} $$::jsonb),
        ('flow.get_template', $$ {"type":"object","additionalProperties":false,"properties":{"flow_template_id":{"type":"string","format":"uuid","description":"Flow template identifier"}},"required":["flow_template_id"]} $$::jsonb),
        ('flow.get_execution', $$ {"type":"object","additionalProperties":false,"properties":{"flow_node_execution_id":{"type":"string","format":"uuid","description":"Flow node execution identifier"}},"required":["flow_node_execution_id"]} $$::jsonb),
        ('schedule.list', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"}},"required":["project_id"]} $$::jsonb),
        ('merge_queue.status', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"}},"required":["project_id"]} $$::jsonb),

        ('file.write', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Target file path"},"content":{"type":"string","description":"File content"},"encoding":{"type":"string","enum":["utf8","base64"],"description":"Input content encoding"},"create_dirs":{"type":"boolean","description":"Create missing parent directories"}},"required":["path"]} $$::jsonb),
        ('file.edit', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Target file path"},"old_string":{"type":"string","description":"String to replace"},"new_string":{"type":"string","description":"Replacement string"},"replace_all":{"type":"boolean","description":"Replace every match"}},"required":["path","old_string","new_string"]} $$::jsonb),
        ('file.delete', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Target file path"}},"required":["path"]} $$::jsonb),
        ('git.commit', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Repository path"},"message":{"type":"string","description":"Commit message"},"all":{"type":"boolean","description":"Stage all tracked and untracked changes"},"paths":{"type":"array","items":{"type":"string"},"description":"Specific paths to stage"}},"required":["message"]} $$::jsonb),
        ('git.push', $$ {"type":"object","additionalProperties":false,"properties":{"path":{"type":"string","description":"Repository path"},"remote":{"type":"string","description":"Remote name"},"branch":{"type":"string","description":"Branch to push"},"force":{"type":"boolean","description":"Force push"}}} $$::jsonb),
        ('cli.execute', $$ {"type":"object","additionalProperties":false,"properties":{"command":{"type":"string","description":"Shell command to execute"},"working_directory":{"type":"string","description":"Optional working directory"},"timeout_seconds":{"type":"integer","minimum":1,"description":"Optional timeout in seconds"},"env_overrides":{"type":"object","additionalProperties":{"type":"string"},"description":"Environment variable overrides"}},"required":["command"]} $$::jsonb),
        ('memory.record', $$ {"type":"object","additionalProperties":false,"properties":{"content":{"type":"string","description":"Memory content"},"scope":{"type":"string","enum":["org","project","agent"],"description":"Memory scope"},"sensitivity":{"type":"string","description":"Sensitivity label"},"tags":{"type":"array","items":{"type":"string"},"description":"Tags"}},"required":["content"]} $$::jsonb),
        ('project.create', $$ {"type":"object","additionalProperties":false,"properties":{"name":{"type":"string","description":"Project display name"},"slug":{"type":"string","description":"Project slug"},"description":{"type":"string","description":"Project description"},"delivery_mode":{"type":"string","enum":["gated","continuous"],"description":"Delivery mode"}},"required":["name"]} $$::jsonb),
        ('project.update', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"},"name":{"type":"string","description":"Updated display name"},"description":{"type":"string","description":"Updated description"},"delivery_mode":{"type":"string","enum":["gated","continuous"],"description":"Updated delivery mode"}},"required":["project_id"]} $$::jsonb),
        ('task.create', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"},"title":{"type":"string","description":"Task title"},"description":{"type":"string","description":"Task description"},"flow_template_id":{"type":"string","format":"uuid","description":"Optional flow template id"},"requires_human_review":{"type":"boolean","description":"Whether human review is required"}},"required":["project_id","title"]} $$::jsonb),
        ('task.update', $$ {"type":"object","additionalProperties":false,"properties":{"task_id":{"type":"string","format":"uuid","description":"Task identifier"},"title":{"type":"string","description":"Updated task title"},"description":{"type":"string","description":"Updated task description"},"work_status":{"type":"string","description":"Updated work status"}},"required":["task_id"]} $$::jsonb),
        ('task.add_dependency', $$ {"type":"object","additionalProperties":false,"properties":{"source_type":{"type":"string","description":"Source node type"},"source_id":{"type":"string","format":"uuid","description":"Source task or subtask id"},"depends_on_type":{"type":"string","description":"Dependency node type"},"depends_on_id":{"type":"string","format":"uuid","description":"Dependency target id"}},"required":["source_type","source_id","depends_on_type","depends_on_id"]} $$::jsonb),
        ('task.remove_dependency', $$ {"type":"object","additionalProperties":false,"properties":{"dependency_id":{"type":"string","format":"uuid","description":"Dependency edge id"}},"required":["dependency_id"]} $$::jsonb),
        ('subtask.create', $$ {"type":"object","additionalProperties":false,"properties":{"flow_node_execution_id":{"type":"string","format":"uuid","description":"Flow node execution id"},"title":{"type":"string","description":"Subtask title"},"description":{"type":"string","description":"Subtask description"},"assignee_type":{"type":"string","description":"Assignee principal type"},"assignee_id":{"type":"string","format":"uuid","description":"Assignee principal id"}},"required":["flow_node_execution_id","title"]} $$::jsonb),
        ('subtask.update', $$ {"type":"object","additionalProperties":false,"properties":{"subtask_id":{"type":"string","format":"uuid","description":"Subtask identifier"},"status":{"type":"string","description":"Updated subtask status"},"title":{"type":"string","description":"Updated subtask title"},"description":{"type":"string","description":"Updated subtask description"}},"required":["subtask_id"]} $$::jsonb),
        ('flow.advance', $$ {"type":"object","additionalProperties":false,"properties":{"flow_node_execution_id":{"type":"string","format":"uuid","description":"Flow node execution id"},"commit_sha":{"type":"string","description":"Optional commit SHA recorded before advancing"}},"required":["flow_node_execution_id"]} $$::jsonb),
        ('flow.review_decision', $$ {"type":"object","additionalProperties":false,"properties":{"flow_node_execution_id":{"type":"string","format":"uuid","description":"Flow node execution id"},"decision":{"type":"string","enum":["approve","reject"],"description":"Review decision"}},"required":["flow_node_execution_id","decision"]} $$::jsonb),
        ('flow.create_template', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"},"name":{"type":"string","description":"Template display name"},"nodes":{"type":"array","description":"Optional node definitions","items":{"type":"object","additionalProperties":false,"properties":{"display_name":{"type":"string"},"node_type":{"type":"string"},"tool_domains":{"type":"array","items":{"type":"string"}}}}}},"required":["project_id","name"]} $$::jsonb),
        ('schedule.create', $$ {"type":"object","additionalProperties":false,"properties":{"project_id":{"type":"string","format":"uuid","description":"Project identifier"},"flow_template_id":{"type":"string","format":"uuid","description":"Flow template id"},"cron":{"type":"string","description":"Cron expression"},"overlap_policy":{"type":"string","enum":["skip","enqueue"],"description":"Overlap policy"},"max_duration_ms":{"type":"integer","minimum":1,"description":"Optional max run duration"}},"required":["project_id","flow_template_id","cron"]} $$::jsonb),
        ('schedule.update', $$ {"type":"object","additionalProperties":false,"properties":{"schedule_id":{"type":"string","format":"uuid","description":"Schedule identifier"},"cron":{"type":"string","description":"Updated cron expression"},"overlap_policy":{"type":"string","enum":["skip","enqueue"],"description":"Updated overlap policy"}},"required":["schedule_id"]} $$::jsonb),
        ('schedule.delete', $$ {"type":"object","additionalProperties":false,"properties":{"schedule_id":{"type":"string","format":"uuid","description":"Schedule identifier"}},"required":["schedule_id"]} $$::jsonb),
        ('agent.create_temp', $$ {"type":"object","additionalProperties":false,"properties":{"name":{"type":"string","description":"Temporary agent display name"},"system_prompt":{"type":"string","description":"Agent system prompt"},"scope_type":{"type":"string","enum":["project"],"description":"Temp scope type"},"scope_id":{"type":"string","format":"uuid","description":"Project id"},"ttl_seconds":{"type":"integer","minimum":1,"description":"Optional TTL in seconds"}},"required":["name","scope_type","scope_id"]} $$::jsonb),
        ('agent.update', $$ {"type":"object","additionalProperties":false,"properties":{"agent_id":{"type":"string","format":"uuid","description":"Agent identifier"},"system_prompt":{"type":"string","description":"Updated system prompt"},"operator_instructions":{"type":"string","description":"Updated operator instructions"},"tool_allow_list":{"type":"array","items":{"type":"string"},"description":"Allowed tool patterns"},"tool_deny_list":{"type":"array","items":{"type":"string"},"description":"Denied tool patterns"}},"required":["agent_id"]} $$::jsonb),
        ('session.create', $$ {"type":"object","additionalProperties":false,"properties":{"scope_type":{"type":"string","description":"Session scope type"},"scope_id":{"type":"string","format":"uuid","description":"Scope identifier"},"mode":{"type":"string","enum":["sync","async"],"description":"Session mode"},"title":{"type":"string","description":"Session title"}},"required":["scope_type","scope_id"]} $$::jsonb),
        ('session.invite_agent', $$ {"type":"object","additionalProperties":false,"properties":{"session_id":{"type":"string","format":"uuid","description":"Session identifier"},"agent_id":{"type":"string","format":"uuid","description":"Agent identifier"}},"required":["session_id","agent_id"]} $$::jsonb),
        ('message.send', $$ {"type":"object","additionalProperties":false,"properties":{"session_id":{"type":"string","format":"uuid","description":"Session identifier"},"content":{"type":"string","description":"Message content"},"role":{"type":"string","enum":["user","assistant","system","tool_call","tool_result"],"description":"Message role"}},"required":["session_id","content"]} $$::jsonb),
        ('email.compose', $$ {"type":"object","additionalProperties":false,"properties":{"to":{"type":"array","items":{"type":"string"},"description":"Recipient addresses"},"cc":{"type":"array","items":{"type":"string"},"description":"CC addresses"},"subject":{"type":"string","description":"Draft email subject"},"body":{"type":"string","description":"Draft email body"}},"required":["subject","body"]} $$::jsonb),
        ('slack.post', $$ {"type":"object","additionalProperties":false,"properties":{"channel":{"type":"string","description":"Slack channel name or id"},"text":{"type":"string","description":"Slack message body"},"thread_ts":{"type":"string","description":"Optional thread timestamp"}},"required":["channel","text"]} $$::jsonb),

        ('browser.navigate', $$ {"type":"object","additionalProperties":false,"properties":{"url":{"type":"string","description":"Destination URL"},"wait_until":{"type":"string","description":"Optional wait strategy"},"timeout_ms":{"type":"integer","minimum":1,"description":"Navigation timeout in milliseconds"}},"required":["url"]} $$::jsonb),
        ('browser.click', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Element selector"},"button":{"type":"string","enum":["left","middle","right"],"description":"Mouse button"},"timeout_ms":{"type":"integer","minimum":1,"description":"Click timeout"}},"required":["selector"]} $$::jsonb),
        ('browser.type', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Element selector"},"text":{"type":"string","description":"Text to type"},"delay_ms":{"type":"integer","minimum":0,"description":"Optional key delay"},"timeout_ms":{"type":"integer","minimum":1,"description":"Type timeout"}},"required":["selector","text"]} $$::jsonb),
        ('browser.select', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Select element selector"},"value":{"type":"string","description":"Option value"},"timeout_ms":{"type":"integer","minimum":1,"description":"Select timeout"}},"required":["selector","value"]} $$::jsonb),
        ('browser.hover', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Element selector"},"timeout_ms":{"type":"integer","minimum":1,"description":"Hover timeout"}},"required":["selector"]} $$::jsonb),
        ('browser.scroll', $$ {"type":"object","additionalProperties":false,"properties":{"x":{"type":"integer","description":"Horizontal scroll delta"},"y":{"type":"integer","description":"Vertical scroll delta"},"selector":{"type":"string","description":"Optional scroll target selector"}}} $$::jsonb),
        ('browser.press_key', $$ {"type":"object","additionalProperties":false,"properties":{"key":{"type":"string","description":"Key name"},"modifiers":{"type":"array","items":{"type":"string"},"description":"Optional key modifiers"}},"required":["key"]} $$::jsonb),
        ('browser.screenshot', $$ {"type":"object","additionalProperties":false,"properties":{"full_page":{"type":"boolean","description":"Capture full page"},"format":{"type":"string","enum":["png","jpeg"],"description":"Image format"},"quality":{"type":"integer","minimum":1,"maximum":100,"description":"JPEG quality"}}} $$::jsonb),
        ('browser.extract_text', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Optional selector to scope extraction"},"include_hidden":{"type":"boolean","description":"Include hidden elements"}}} $$::jsonb),
        ('browser.extract_structured', $$ {"type":"object","additionalProperties":false,"properties":{"schema":{"type":"object","description":"Desired structured output shape"},"selector":{"type":"string","description":"Optional extraction scope selector"},"instruction":{"type":"string","description":"Optional extraction instruction"}},"required":["schema"]} $$::jsonb),
        ('browser.get_page_info', $$ {"type":"object","additionalProperties":false,"properties":{}} $$::jsonb),
        ('browser.wait_for', $$ {"type":"object","additionalProperties":false,"properties":{"selector":{"type":"string","description":"Selector to wait for"},"state":{"type":"string","enum":["attached","detached","visible","hidden"],"description":"Desired element state"},"timeout_ms":{"type":"integer","minimum":1,"description":"Wait timeout"}}} $$::jsonb),
        ('browser.wait_for_navigation', $$ {"type":"object","additionalProperties":false,"properties":{"timeout_ms":{"type":"integer","minimum":1,"description":"Wait timeout"}}} $$::jsonb),
        ('browser.back', $$ {"type":"object","additionalProperties":false,"properties":{}} $$::jsonb),
        ('browser.forward', $$ {"type":"object","additionalProperties":false,"properties":{}} $$::jsonb),
        ('browser.refresh', $$ {"type":"object","additionalProperties":false,"properties":{}} $$::jsonb),
        ('browser.evaluate', $$ {"type":"object","additionalProperties":false,"properties":{"script":{"type":"string","description":"JavaScript source code"},"args":{"type":"array","description":"Arguments passed to script","items":{}},"timeout_ms":{"type":"integer","minimum":1,"description":"Evaluation timeout"}},"required":["script"]} $$::jsonb),

        ('mcp.discover', $$ {"type":"object","additionalProperties":false,"properties":{"connection_id":{"type":"string","format":"uuid","description":"MCP connection identifier"},"filter":{"type":"string","description":"Optional tool name filter"}},"required":["connection_id"]} $$::jsonb)
)
UPDATE tool_definition td
SET input_schema = tool_schemas.input_schema
FROM tool_schemas
WHERE td.name = tool_schemas.name;
